        await(c,w,CopycatRenderingTest::receipts,250,"Actual original finite wrappers/materials/named stone/barrel cargo were not conserved");c.waitFor(client->CopycatNativeProbe.complete()&&client.level.getBlockEntity(BARREL) instanceof CopycatBlockEntity barrel&&ItemStack.matches(barrel.getConsumedItem(),cargo()),300);c.runOnClient(client->CopycatNativeProbe.verify());standOverview(c,w);screenshot(c,w,"create-vulkan-copycat-eight-paid-native-owners-source-uv-culling-tint-light-bars-and-trapdoor");
        var oldModels=c.computeOnClient(client->POSITIONS.stream().map(pos->client.getModelManager().getBlockStateModelSet().get(client.level.getBlockState(pos))).toList());c.runOnClient(client->CopycatNativeProbe.begin("create-vulkan-copycat-actual-resource-reload",expected(false)));var reload=c.computeOnClient(Minecraft::reloadResourcePacks);c.waitFor(client->reload.isDone()&&client.gui.overlay()==null,650);reload.join();c.waitFor(client->CopycatNativeProbe.complete(),300);c.runOnClient(client->{for(int index=0;index<POSITIONS.size();index++)if(client.getModelManager().getBlockStateModelSet().get(client.level.getBlockState(POSITIONS.get(index)))==oldModels.get(index))throw new AssertionError("Actual resource reload retained stale Copycat model owner");CopycatNativeProbe.verify();});screenshot(c,w,"create-vulkan-copycat-real-native-resource-reload-preserves-original-material-owners");
